python3 -c '
import re
xml=open("unpacked/word/document.xml",encoding="ascii").read()
for m in re.finditer(r"<w:rPr>.*?</w:rPr>",xml,re.S):
    block=m.group(0)
    t=re.search(r"<w:t[^>]*>(.*?)</w:t>",xml[m.end():],re.S)
    if "<w:u" in block:
        print("UNDERLINED:", (t.group(1) if t else "?")[:50])
    else:
        txt=t.group(1).strip() if t else ""
        if txt: print("normal    :", txt[:50])
'

